package javafx.scene.control; import javafx.scene.Parent; import javafx.collections.ObservableList; import java.util.function.Consumer; public class ComboBox<T> extends Parent { private final ObservableList<T> items=new ObservableList<>(); private T value; public ObservableList<T> getItems(){return items;} public void setValue(T v){value=v;} public T getValue(){return value;} public void setOnAction(Consumer<Object> c){} }
